public static void main(Args _args)
{
    Set transferredSites = new Set(Types::String);
    Set visitedSites = new Set(Types::String);
    container toVisit;

    toVisit = ["Lavertfood"];

    //ListIterator iterator = new ListIterator(toVisit);

    for (int i = 1; i<= conLen(toVisit); i++)
    {
        str currentSite = conPeek(toVisit, i);

        //toVisit.removeFirst();

        // Skip if already visited
        if (visitedSites.in(currentSite))
        continue;

        visitedSites.add(currentSite);

        METReqItemTableInventDimView metReqItemTableInventDimView;
        METItemStatusWarehouses metItemStatusWarehouses;

        while select metReqItemTableInventDimView
        where metReqItemTableInventDimView.ItemId == '13011'
        && metReqItemTableInventDimView.InventSiteId != currentSite
        && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
        && metReqItemTableInventDimView.MainWarehouseInventSiteId == currentSite
        notexists join metItemStatusWarehouses
        where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
        {
            if (!transferredSites.in(metReqItemTableInventDimView.InventSiteId))
            {
                transferredSites.add( metReqItemTableInventDimView.InventSiteId);
                toVisit += metReqItemTableInventDimView.InventSiteId; // Enqueue next site
            }
        }
    }
    // return transferredSites;


    SetEnumerator   setEnumerator;

    if (!transferredSites.empty())
    {
        setEnumerator = transferredSites.getEnumerator();
        setEnumerator.reset();
        while (setEnumerator.moveNext())
        {
            info(strfmt("Site: %1",setEnumerator.current()));
        }
    }
}
